INSERT INTO attendances(enrollment_id,class_session_id,session_date,status,has_permission,recorded_by,recorded_by_name) SELECT e.id,se.id,se.session_date,CASE WHEN e.student_id%13=0 THEN 'ABSENT' WHEN e.student_id%11=0 THEN 'LATE' ELSE 'PRESENT' END,0,t.account_id,t.full_name FROM enrollments e JOIN school_classes c ON c.id=e.class_id JOIN class_sessions se ON se.class_id=c.id JOIN teachers t ON t.id=se.teacher_id WHERE se.status='COMPLETED' AND EXISTS(SELECT 1 FROM enrollment_periods ep WHERE ep.enrollment_id=e.id AND ep.active_from<=se.session_date AND (ep.active_until IS NULL OR ep.active_until>=se.session_date)) AND NOT EXISTS(SELECT 1 FROM attendances a WHERE a.enrollment_id=e.id AND a.session_date=se.session_date);
