INSERT IGNORE INTO personnel_code_numbers(id) VALUES (18);
INSERT IGNORE INTO student_code_numbers(id) VALUES (400);
INSERT INTO seed_assertions VALUES ('four branches',IF((SELECT COUNT(*)=4 FROM branches),1,0));
INSERT INTO seed_assertions VALUES ('admin branch distribution',IF((SELECT COUNT(*)=4 FROM account_branches b JOIN accounts a ON a.id=b.account_id WHERE b.status=1 AND ((a.username='admin1' AND b.branch_id IN (1,2)) OR (a.username='admin2' AND b.branch_id IN (3,4)))),1,0));
INSERT INTO seed_assertions VALUES ('two branches per admin',IF((SELECT COUNT(*)=2 FROM (SELECT a.id FROM accounts a JOIN account_branches b ON b.account_id=a.id AND b.status=1 WHERE a.role='ADMIN' GROUP BY a.id HAVING COUNT(*)=2) x),1,0));
INSERT INTO seed_assertions VALUES ('two staff per branch',IF((SELECT COUNT(*)=4 FROM (SELECT b.branch_id FROM account_branches b JOIN accounts a ON a.id=b.account_id WHERE b.status=1 AND a.role='STAFF' GROUP BY b.branch_id HAVING COUNT(*)=2) x),1,0));
INSERT INTO seed_assertions VALUES ('100 students per branch',IF((SELECT COUNT(*)=4 FROM (SELECT branch_id FROM students GROUP BY branch_id HAVING COUNT(*)=100) x),1,0));
INSERT INTO seed_assertions VALUES ('20 leads per branch',IF((SELECT COUNT(*)=4 FROM (SELECT branch_id FROM leads GROUP BY branch_id HAVING COUNT(*)=20) x),1,0));
INSERT INTO seed_assertions VALUES ('25 enrollments per class',IF((SELECT COUNT(*)=16 FROM (SELECT class_id FROM enrollments WHERE study_status IN ('STUDYING','RESERVED') GROUP BY class_id HAVING COUNT(*)=25) x),1,0));
INSERT INTO seed_assertions VALUES ('no class over capacity',IF((SELECT COUNT(*)=0 FROM school_classes c JOIN rooms r ON r.id=c.room_id JOIN courses co ON co.id=c.course_id WHERE c.max_size>r.capacity OR c.max_size>co.max_students OR c.current_size>c.max_size),1,0));
INSERT INTO seed_assertions VALUES ('no timetable conflict',IF((SELECT COUNT(*)=0 FROM class_sessions a JOIN class_sessions b ON a.id<b.id AND a.session_date=b.session_date AND a.start_time<b.end_time AND b.start_time<a.end_time AND (a.teacher_id=b.teacher_id OR a.room_id=b.room_id) WHERE a.status<>'CANCELLED' AND b.status<>'CANCELLED'),1,0));
INSERT INTO seed_assertions VALUES ('correct tuition ledger',IF((SELECT COUNT(*)=0 FROM tuition t WHERE t.paid_amount<>(SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.tuition_id=t.id AND p.status='PAID')-(SELECT COALESCE(SUM(c.amount),0) FROM payment_corrections c WHERE c.tuition_id=t.id)),1,0));
INSERT INTO seed_assertions VALUES ('every student enrolled',IF((SELECT COUNT(*)=0 FROM students s WHERE NOT EXISTS(SELECT 1 FROM enrollments e WHERE e.student_id=s.id AND e.study_status IN ('STUDYING','RESERVED'))),1,0));
INSERT INTO seed_assertions VALUES ('student accounts match',IF((SELECT COUNT(*)=0 FROM students s LEFT JOIN accounts a ON a.id=s.account_id WHERE a.id IS NULL OR a.role<>'STUDENT' OR a.branch_id<>s.branch_id),1,0));
INSERT INTO seed_assertions VALUES ('enrollment branch and tuition',IF((SELECT COUNT(*)=0 FROM enrollments e JOIN students s ON s.id=e.student_id JOIN school_classes c ON c.id=e.class_id LEFT JOIN tuition t ON t.enrollment_id=e.id WHERE s.branch_id<>c.branch_id OR t.id IS NULL OR t.student_id<>s.id OR t.class_id<>c.id),1,0));
INSERT INTO seed_assertions VALUES ('attendance respects enrollment dates',IF((SELECT COUNT(*)=0 FROM attendances a JOIN enrollments e ON e.id=a.enrollment_id JOIN class_sessions se ON se.id=a.class_session_id WHERE e.class_id<>se.class_id OR a.session_date<>se.session_date OR NOT EXISTS(SELECT 1 FROM enrollment_periods ep WHERE ep.enrollment_id=e.id AND ep.active_from<=a.session_date AND (ep.active_until IS NULL OR ep.active_until>=a.session_date))),1,0));
INSERT INTO seed_assertions VALUES ('exam roster respects effective dates',IF((SELECT COUNT(*)=0 FROM exam_candidates ec JOIN exams ex ON ex.id=ec.exam_id JOIN enrollments e ON e.id=ec.enrollment_id WHERE e.student_id<>ec.student_id OR e.class_id<>ex.class_id OR NOT EXISTS(SELECT 1 FROM enrollment_periods ep WHERE ep.enrollment_id=e.id AND ep.active_from<=ex.exam_date AND (ep.active_until IS NULL OR ep.active_until>=ex.exam_date))),1,0));
